#!/usr/bin/env node
// Generates app/src/main/java/dev/rei/android/ui/components/BotArt.kt from the built-in bot artwork in
// apps/web/src/components/BotAvatar.tsx, so Android draws the same six cut-paper bots as web.
// Run from anywhere: `node apps/android/tools/generate-bots.mjs`. The generated file is checked in.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { shapePath } from "./svg.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "../../..");
const source = readFileSync(join(root, "apps/web/src/components/BotAvatar.tsx"), "utf8");
const out = join(here, "../app/src/main/java/dev/rei/android/ui/components/BotArt.kt");

const art = source.match(/const ART: Record<BotId, ReactNode> = \{([\s\S]*?)\n\};/);
if (!art) throw new Error("Could not find ART in BotAvatar.tsx");
const bots = [...art[1].matchAll(/^ {2}(\w+): \(\n\s*<>([\s\S]*?)<\/>\n\s*\),/gm)];
if (bots.length === 0) throw new Error("No bots found");

const attrs = (text) => Object.fromEntries([...text.matchAll(/([\w-]+)="([^"]*)"/g)].map(([, k, v]) => [k, v]));
const kotlin = [];
for (const [, id, body] of bots) {
  const shapes = [];
  for (const [, tag, rest] of body.matchAll(/<(path|rect|ellipse)\s+([\s\S]*?)\/>/g)) {
    const a = attrs(rest);
    const classes = (a.className ?? "").split(/\s+/);
    const d = shapePath(tag, a);
    const eye = classes.includes("bot-eye");
    const line = classes.includes("bot-line")
      ? classes.includes("bot-strong")
        ? "Strong"
        : classes.includes("bot-light")
          ? "Light"
          : classes.includes("bot-fold")
            ? "Fold"
            : "Ink"
      : null;
    const fill = eye
      ? "Eye"
      : classes.includes("bot-main")
        ? "Main"
        : classes.includes("bot-shade")
          ? "Shade"
          : classes.includes("bot-paper")
            ? "Paper"
            : null;
    shapes.push(
      `        BotShape(${JSON.stringify(d)}, fill = ${fill ? `BotFill.${fill}` : "null"}, line = ${line ? `BotLine.${line}` : "null"}, edge = ${classes.includes("bot-edge")}, eye = ${eye}),`,
    );
  }
  kotlin.push(`    "${id}" to listOf(\n${shapes.join("\n")}\n    ),`);
}

writeFileSync(
  out,
  `// GENERATED by apps/android/tools/generate-bots.mjs from apps/web/src/components/BotAvatar.tsx. Do not edit by hand.
// Regenerate with: node apps/android/tools/generate-bots.mjs
package dev.rei.android.ui.components

/** What a shape is filled with (the \`bot-*\` classes in web's app.css). */
internal enum class BotFill { Main, Shade, Paper, Eye }

/** The look of a stroked shape: ink, a heavier ink, paper, or a darker fold of the bot's own tint. */
internal enum class BotLine { Ink, Strong, Light, Fold }

internal data class BotShape(
    val d: String,
    val fill: BotFill?,
    val line: BotLine?,
    val edge: Boolean,
    val eye: Boolean,
)

/** Artwork on a 64 x 64 grid, keyed by the id after \`bot:\`, drawn back to front. */
internal val BotArt: Map<String, List<BotShape>> = mapOf(
${kotlin.join("\n")}
)
`,
);
console.log(`Wrote ${bots.length} bots to ${out}`);
